import base64
import sys
import zlib

import numpy as np
import matplotlib.pyplot as plt

_ARRAYS = [
    '',
    '',
]


def _array(i):
    return np.frombuffer(zlib.decompress(base64.b64decode(_ARRAYS[i])), dtype='<f8').copy()


def build_figure():
    a = [_array(i) for i in range(len(_ARRAYS))]
    fig, ax = plt.subplots()
    ax.plot(a[0], a[1], label='C12 heating')
    ax.set_xscale('log')
    ax.set_yscale('log')
    ax.set_xlabel('Energy [eV]')
    ax.set_xlim(1e-5, 20000000.0)
    ax.set_ylabel('Heating Cross Section [eV-barn]')
    ax.legend(loc='best')
    ax.set_title('Cross Section Plot For C12')
    return fig


if __name__ == '__main__':
    build_figure().savefig(sys.argv[1] if len(sys.argv) > 1 else 'xs_c12_heating.png')
